function main(): void {
  const S = Symbol('s');
  const T = Symbol('t');
  const o: any = { a: 1, [S]: 2 };
  Object.defineProperty(o, T, { value: 9, enumerable: false });
  const c: any = Object.assign({}, o);
  console.log(c[S], c[T], Object.getOwnPropertySymbols(c).length);
  const sp: any = { ...o };
  console.log(sp[S], sp[T], Object.getOwnPropertySymbols(sp).length);
  const { a, ...rest }: any = o;
  console.log(a, rest[S], rest[T], Object.getOwnPropertySymbols(rest).length);
}
